// src/lib/server/stravaSetup.js
// One-time Strava webhook subscription, driven by sync_settings (verify token generated by the migration).

import { ensureWebhookSubscription } from './stravaProvider.js'
import { ImportError } from './importErrors.js'

export async function getSetting(service, key) {
  const { data } = await service.from('sync_settings').select('value').eq('key', key).maybeSingle()
  return data?.value || null
}

/**
 * Creates the Strava push subscription unless one exists. The callback uses the production
 * `app_base_url` (falls back to `fallbackOrigin`) so preview deployments never claim the single subscription.
 */
export async function ensureStravaWebhook(service, fallbackOrigin, deps = {}) {
  const verifyToken = await getSetting(service, 'strava_webhook_verify_token')
  if (!verifyToken) throw new ImportError('Strava webhook verify token is missing (migration not applied).', 500)
  const base = (await getSetting(service, 'app_base_url')) || fallbackOrigin
  return ensureWebhookSubscription({
    callbackUrl: `${base.replace(/\/+$/, '')}/api/webhooks/strava`,
    verifyToken,
    ...deps,
  })
}
